package vn.somehouse;
import static vn.somehouse.ApiTypes.*;import com.fasterxml.jackson.databind.*;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.stereotype.Component;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.beans.factory.annotation.Value;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import java.util.*;
@Component public class SeedBootstrap implements ApplicationRunner {
 final CatalogService catalog;final JdbcTemplate db;final ObjectMapper json;final PasswordEncoder encoder;final TransactionTemplate tx;final String email,password;final boolean seed;
 SeedBootstrap(CatalogService c,JdbcTemplate db,ObjectMapper j,PasswordEncoder e,PlatformTransactionManager tm,@Value("${app.admin-email}")String mail,@Value("${app.admin-password}")String pass,@Value("${app.seed-enabled}")boolean enabled){catalog=c;this.db=db;json=j;encoder=e;tx=new TransactionTemplate(tm);email=mail.trim().toLowerCase(Locale.ROOT);password=pass;seed=enabled;}
 public void run(ApplicationArguments args)throws Exception{
  JsonNode defaults=json.readTree(getClass().getResourceAsStream("/seed.json"));if(Objects.requireNonNull(db.queryForObject("SELECT COUNT(*) FROM site_settings",Integer.class))==0)db.update("INSERT INTO site_settings(id,data_json) VALUES(1,?)",catalog.write(defaults.path("settings")));
  if(seed&&Objects.requireNonNull(db.queryForObject("SELECT COUNT(*) FROM catalog_items",Integer.class))==0){JsonNode root=json.readTree(getClass().getResourceAsStream("/seed.json"));tx.executeWithoutResult(s->{for(JsonNode n:root.path("items")){try{catalog.create(json.treeToValue(n,ItemInput.class));}catch(Exception e){throw new IllegalStateException("Cannot import item "+n.path("slug").asText(),e);}}if(Objects.requireNonNull(db.queryForObject("SELECT COUNT(*) FROM site_settings",Integer.class))==0)db.update("INSERT INTO site_settings(id,data_json) VALUES(1,?)",catalog.write(root.path("settings")));});}
  if(!email.isBlank()&&Objects.requireNonNull(db.queryForObject("SELECT COUNT(*) FROM app_users WHERE email=?",Integer.class,email))==0){if(password.length()<12||password.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new IllegalStateException("APP_ADMIN_PASSWORD must contain at least 12 characters and at most 72 UTF-8 bytes.");db.update("INSERT INTO app_users(email,password_hash) VALUES(?,?)",email,encoder.encode(password));}
 }
}
